SELECT c.ClientID, c.LastName & ", " & c.FirstName AS ClientName, s.ServiceCode, s.ServiceName, csn.HoursPerWeek AS RequestedHours, csn.Priority, csn.FiscalYear
FROM tblServices AS s INNER JOIN (tblClients AS c INNER JOIN tblClientServiceNeeds AS csn ON c.ClientID = csn.ClientID) ON s.ServiceID = csn.ServiceID
WHERE (((csn.ClientServiceNeedID) Not In (SELECT ClientServiceNeedID FROM tblClientServicePlan
    WHERE Status = 'Approved'
)))
ORDER BY c.LastName, c.FirstName, csn.Priority;
